package com.biocircular.compostaje.mapper; import com.biocircular.compostaje.dto.Responses; import com.biocircular.compostaje.entity.*; import java.util.*;
public final class CompostajeMapper { private CompostajeMapper(){} public static Responses.TipoResiduo tipo(TipoResiduo x){return new Responses.TipoResiduo(x.getId(),x.getCodigo(),x.getNombre(),x.getDescripcion(),x.isActivo());} public static Responses.Ingreso ingreso(IngresoResiduo x){return new Responses.Ingreso(x.getId(),x.getTipoResiduo().getId(),x.getTipoResiduo().getNombre(),x.getPesoKg(),x.getFechaHora(),x.getResponsableId());} public static Responses.Lote lote(Lote x){return new Responses.Lote(x.getId(),x.getCodigo(),x.getEstado(),x.getFechaInicio(),x.getFechaCierre(),x.getResponsableId(),x.getIngresos().stream().map(IngresoResiduo::getId).collect(java.util.stream.Collectors.toSet()));} public static Responses.Etapa etapa(LoteEtapa x){return new Responses.Etapa(x.getId(),x.getEtapa().getId(),x.getEtapa().getNombre(),x.getEstado(),x.getFechaInicio(),x.getFechaFin(),x.getResponsableId());} public static Responses.Observacion observacion(ObservacionEtapa x){return new Responses.Observacion(x.getId(),x.getLoteEtapa().getId(),x.getNota(),x.getFechaHora(),x.getResponsableId());} public static Responses.Compost compost(Compost x){return new Responses.Compost(x.getId(),x.getLote().getId(),x.getCantidadKg(),x.getFechaProduccion(),x.isAptoEntrega());} public static Responses.Movimiento movimiento(MovimientoInventario x){return new Responses.Movimiento(x.getId(),x.getTipo(),x.getCantidadKg(),x.getMotivo(),x.getFechaHora());} }
